<?php
declare(strict_types=1);
require_once __DIR__ . '/../includes/bootstrap.php';require_once __DIR__ . '/../includes/auth.php';
$user=current_user();$staffRoles=['Administrator','Head','Teacher','Bursar','Clerk'];if(!$user||!in_array($user['role'],$staffRoles,true)){http_response_code(403);exit('Access denied.');}if($_SERVER['REQUEST_METHOD']!=='POST'||!verify_csrf()){http_response_code(419);exit('This form has expired. Refresh the page and try again.');}
$type=(string)($_POST['leave_type']??'');$start=trim((string)($_POST['start_on']??''));$end=trim((string)($_POST['end_on']??''));$reason=trim((string)($_POST['reason']??''));$validDate=static function(string $v):bool{if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$v))return false;$d=DateTimeImmutable::createFromFormat('!Y-m-d',$v);$e=DateTimeImmutable::getLastErrors();return $d!==false&&$d->format('Y-m-d')===$v&&($e===false||(!$e['warning_count']&&!$e['error_count']));};
if(!in_array($type,['Annual','Sick','Maternity','Paternity','Compassionate','Study','Unpaid','Other'],true)||!$validDate($start)||!$validDate($end)||$end<$start||strlen($reason)>1000){$_SESSION['error']='Choose a leave type and valid start/end dates, with the end date on or after the start date.';header('Location: ../?page=staffing');exit;}
$pdo=db();try{$pdo->beginTransaction();$q=$pdo->prepare("SELECT id FROM users WHERE id=:id AND active=1 AND role IN ('Administrator','Head','Teacher','Bursar','Clerk') FOR UPDATE");$q->execute(['id'=>$user['id']]);if(!$q->fetch())throw new DomainException('Your active staff account could not be verified.');$q=$pdo->prepare("SELECT id FROM staff_leave_requests WHERE staff_id=:staff AND status IN ('Pending','Approved') AND start_on<=:end_on AND end_on>=:start_on LIMIT 1");$q->execute(['staff'=>$user['id'],'end_on'=>$end,'start_on'=>$start]);if($q->fetch())throw new DomainException('You already have a pending or approved leave request that overlaps these dates.');$q=$pdo->prepare('INSERT INTO staff_leave_requests(staff_id,leave_type,start_on,end_on,reason) VALUES(:staff,:type,:start,:end,:reason)');$q->execute(['staff'=>$user['id'],'type'=>$type,'start'=>$start,'end'=>$end,'reason'=>$reason?:null]);$id=(int)$pdo->lastInsertId();$q=$pdo->prepare("INSERT INTO staff_leave_reviews(leave_request_id,from_status,to_status,notes,reviewed_by) VALUES(:id,NULL,'Pending','Leave request submitted',:user)");$q->execute(['id'=>$id,'user'=>$user['id']]);audit_log('staff.leave_requested','staff_leave_requests',$id,['leave_type'=>$type,'start_on'=>$start,'end_on'=>$end]);$pdo->commit();$_SESSION['notice']='Leave request submitted for school leadership review.';}catch(DomainException $e){if($pdo->inTransaction())$pdo->rollBack();$_SESSION['error']=$e->getMessage();}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();error_log('Staff leave request failed: '.$e->getMessage());$_SESSION['error']='Could not submit the leave request.';}header('Location: ../?page=staffing');exit;
